def transform(g):
    h,w=len(g),len(g[0])
    cs={(i,j) for i in range(h) for j in range(w) if g[i][j]==8}
    out=[[0]*w for _ in range(h)]
    def orient(s):
        # L-triomino: find corner cell with 2 neighbors in s
        for c in s:
            arms=tuple(sorted((y-c[0],x-c[1]) for y,x in s-{c}))
            if arms==((0,1),(1,0)): return 5   # R+D: unseen, guess
            if arms==((0,-1),(1,0)): return 3  # L+D
            if arms==((0,1),(-1,0)): return 4  # R+U
            if arms==((0,-1),(-1,0)): return 2 # L+U
    tiles=[]
    for i in range(h-1):
        for j in range(w-1):
            s=frozenset({(i,j),(i,j+1),(i+1,j),(i+1,j+1)})
            if s<=cs: tiles.append((1,s))
            arms=[(0,1),(0,-1),(1,0),(-1,0)]
            for k1 in range(4):
                for k2 in range(k1+1,4):
                    s=frozenset({(i,j),(i+arms[k1][0],j+arms[k1][1]),(i+arms[k2][0],j+arms[k2][1])})
                    if s<=cs and len({(i+arms[k1][0],j+arms[k1][1]),(i+arms[k2][0],j+arms[k2][1])})==2 \
                       and (arms[k1][0]==0)==(arms[k2][0]==0)==False or (arms[k1][0]!=0)!=(arms[k2][0]!=0):
                        tiles.append((orient(s),s))
    tiles=[t for t in tiles if t[1]<=cs]
    sols=[]
    def rec(rem,used):
        if not rem: sols.append(list(used)); return
        c=min(rem)
        for t in tiles:
            if c in t[1] and t[1]<=rem: rec(rem-t[1],used+[t])
    rec(frozenset(cs),[])
    for col,s in sols[0]:
        for y,x in s: out[y][x]=col
    return out
